    fun find(inn: String) = all.firstOrNull { ReferenceSearch.normalize(it.inn)==ReferenceSearch.normalize(inn) }
    fun aliasInn(q: String): String? = all.firstOrNull { g -> (g.aliases + listOfNotNull(g.latin,g.genitive)).any { ReferenceSearch.normalize(it).startsWith(q) } }?.inn
}
